import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    t = int(input_data[0])
    results = []

    for i in range(1, t + 1):
        s = input_data[i]
        count_a = s.count('A')
        count_b = s.count('B')
        count_c = s.count('C')

        if count_a == count_c and count_b == count_a + count_c:
            results.append("YES")
        else:
            results.append("NO")

    for res in results:
        print(res)

if __name__ == "__main__":
    solve()
